package com.jinloes.practice;
final class Workload { static final String UNIT="call"; static final int[] SIZES={4096,8192,16384,32768,65536}; private Workload(){} static Object prepare(int size){ int[] v=new int[size]; int[] p=new int[size]; for(int i=0;i<size;i++){ v[i]=i; p[i]=(i+1)%size; } return new Object[]{v,p}; } static void run(Object state){ Object[] s=(Object[])state; Solution.applyPermutation((int[])s[0],(int[])s[1]); } static int units(int size){ return 1; } }
